/*!
 * \file
 * \ingroup PoromechanicsTests
 * \brief Exact solution and source terms of the plane-strain manufactured solution
 *        for the large-deformation poroelastic model (generated by generate_solution.py).
 */
#ifndef DUMUX_TEST_POROELASTIC_LARGE_DEF_MMS_SOLUTION_HH
#define DUMUX_TEST_POROELASTIC_LARGE_DEF_MMS_SOLUTION_HH

#include <array>
#include <cmath>

namespace Dumux::PoroElasticLargeDefMMS {

//! amplitude of the displacement d = t phi (a, b)
inline constexpr double a = 0.07642789737575947;
inline constexpr double b = 0.03821394868787974;

//! phi and its derivatives phi_x, phi_y, phi_xx, phi_xy, phi_yy
template<class Scalar>
std::array<Scalar, 6> phiDerivatives(Scalar x, Scalar y)
{
    return {
        std::exp((1.0/2.0)*x + (1.0/4.0)*y)*std::sin(M_PI*x)*std::sin(M_PI*y),
        (1.0/2.0)*(std::sin(M_PI*x) + 2*M_PI*std::cos(M_PI*x))*std::exp((1.0/2.0)*x
        + (1.0/4.0)*y)*std::sin(M_PI*y),
        (1.0/4.0)*(std::sin(M_PI*y) + 4*M_PI*std::cos(M_PI*y))*std::exp((1.0/2.0)*x
        + (1.0/4.0)*y)*std::sin(M_PI*x),
        (1.0/4.0)*(-4*std::pow(M_PI, 2)*std::sin(M_PI*x) + std::sin(M_PI*x)
        + 4*M_PI*std::cos(M_PI*x))*std::exp((1.0/2.0)*x + (1.0/4.0)*y)*std::sin(M_PI*y),
        ((1.0/8.0)*std::sin(M_PI*x)*std::sin(M_PI*y)
        + (1.0/2.0)*M_PI*std::sin(M_PI*x)*std::cos(M_PI*y)
        + (1.0/4.0)*M_PI*std::sin(M_PI*y)*std::cos(M_PI*x)
        + std::pow(M_PI, 2)*std::cos(M_PI*x)*std::cos(M_PI*y))*std::exp((1.0/2.0)*x + (1.0/4.0)*y),
        (1.0/16.0)*(-16*std::pow(M_PI, 2)*std::sin(M_PI*y) + std::sin(M_PI*y)
        + 8*M_PI*std::cos(M_PI*y))*std::exp((1.0/2.0)*x + (1.0/4.0)*y)*std::sin(M_PI*x)
    };
}

//! psi and its derivatives psi_x, psi_y, psi_xx, psi_xy, psi_yy
template<class Scalar>
std::array<Scalar, 6> psiDerivatives(Scalar x, Scalar y)
{
    return {
        std::exp(-1.0/2.0*y)*std::sin(M_PI*x)*std::sin(M_PI*y),
        M_PI*std::exp(-1.0/2.0*y)*std::sin(M_PI*y)*std::cos(M_PI*x),
        (1.0/2.0)*(-std::sin(M_PI*y) + 2*M_PI*std::cos(M_PI*y))*std::exp(-1.0/2.0*y)*std::sin(M_PI*x),
        -std::pow(M_PI, 2)*std::exp(-1.0/2.0*y)*std::sin(M_PI*x)*std::sin(M_PI*y),
        (1.0/2.0)*M_PI*(-std::sin(M_PI*y)
        + 2*M_PI*std::cos(M_PI*y))*std::exp(-1.0/2.0*y)*std::cos(M_PI*x),
        (1.0/4.0)*(-4*std::pow(M_PI, 2)*std::sin(M_PI*y) + std::sin(M_PI*y)
        - 4*M_PI*std::cos(M_PI*y))*std::exp(-1.0/2.0*y)*std::sin(M_PI*x)
    };
}

template<class Scalar>
std::array<Scalar, 2> displacement(Scalar x, Scalar y, Scalar t)
{
    const auto [phi, phiX, phiY, phiXX, phiXY, phiYY] = phiDerivatives(x, y);
    return {a*phi*t, b*phi*t};
}

template<class Scalar>
Scalar fluidPressure(Scalar x, Scalar y, Scalar t)
{
    const auto [psi, psiX, psiY, psiXX, psiXY, psiYY] = psiDerivatives(x, y);
    return psi*t;
}

template<class Scalar>
Scalar solidPressure(Scalar x, Scalar y, Scalar t, Scalar K)
{
    const auto [phi, phiX, phiY, phiXX, phiXY, phiYY] = phiDerivatives(x, y);
    const Scalar J = a*phiX*t + b*phiY*t + 1;
    return (1.0/2.0)*K*(std::pow(J, 2) - 1)/J;
}

template<class Scalar>
std::array<Scalar, 2> momentumSource(Scalar x, Scalar y, Scalar t, Scalar G, Scalar K, Scalar alpha)
{
    const auto [phi, phiX, phiY, phiXX, phiXY, phiYY] = phiDerivatives(x, y);
    const auto [psi, psiX, psiY, psiXX, psiXY, psiYY] = psiDerivatives(x, y);
    const Scalar J = a*phiX*t + b*phiY*t + 1;
    const Scalar I1 = std::pow(a, 2)*std::pow(phiY, 2)*std::pow(t, 2)
        + std::pow(b, 2)*std::pow(phiX, 2)*std::pow(t, 2) + std::pow(a*phiX*t + 1, 2)
        + std::pow(b*phiY*t + 1, 2);
    return {
        (1.0/18.0)*t*(-18*G*std::pow(J, 19.0/3.0)*a*(phiXX + phiYY)
        + 12*G*std::pow(J, 16.0/3.0)*(a*phiY*t*(a*phiXY + b*phiYY)
        - b*phiX*t*(std::pow(a, 2)*phiY*phiYY*t + a*phiXY*(a*phiX*t + 1)
        + std::pow(b, 2)*phiX*phiXY*t + b*phiYY*(b*phiY*t + 1)) + (a*phiXX + b*phiXY)*(a*phiX*t + 1)
        + (b*phiY*t + 1)*(std::pow(a, 2)*phiXY*phiY*t + a*phiXX*(a*phiX*t + 1)
        + std::pow(b, 2)*phiX*phiXX*t + b*phiXY*(b*phiY*t + 1))) + 10*G*std::pow(J, 13.0/3.0)*(I1
        + 1)*(b*phiX*t*(a*phiXY + b*phiYY) - (a*phiXX + b*phiXY)*(b*phiY*t + 1))
        + 9*std::pow(J, 5)*(-b*phiX*t*(2*std::pow(J, 2)*(-K*(a*phiXY + b*phiYY) + alpha*psiY)
        + K*(std::pow(J, 2) - 1)*(a*phiXY + b*phiYY)) + (2*std::pow(J, 2)*(-K*(a*phiXX + b*phiXY)
        + alpha*psiX) + K*(std::pow(J, 2) - 1)*(a*phiXX + b*phiXY))*(b*phiY*t + 1)))/std::pow(J, 7),
        (1.0/18.0)*t*(-18*G*std::pow(J, 19.0/3.0)*b*(phiXX + phiYY)
        + 12*G*std::pow(J, 16.0/3.0)*(-a*phiY*t*(std::pow(a, 2)*phiXY*phiY*t + a*phiXX*(a*phiX*t + 1)
        + std::pow(b, 2)*phiX*phiXX*t + b*phiXY*(b*phiY*t + 1)) + b*phiX*t*(a*phiXX + b*phiXY)
        + (a*phiXY + b*phiYY)*(b*phiY*t + 1) + (a*phiX*t + 1)*(std::pow(a, 2)*phiY*phiYY*t
        + a*phiXY*(a*phiX*t + 1) + std::pow(b, 2)*phiX*phiXY*t + b*phiYY*(b*phiY*t + 1)))
        + 10*G*std::pow(J, 13.0/3.0)*(I1 + 1)*(a*phiY*t*(a*phiXX + b*phiXY) - (a*phiXY
        + b*phiYY)*(a*phiX*t + 1)) + 9*std::pow(J, 5)*(-a*phiY*t*(2*std::pow(J, 2)*(-K*(a*phiXX
        + b*phiXY) + alpha*psiX) + K*(std::pow(J, 2) - 1)*(a*phiXX + b*phiXY))
        + (2*std::pow(J, 2)*(-K*(a*phiXY + b*phiYY) + alpha*psiY) + K*(std::pow(J, 2) - 1)*(a*phiXY
        + b*phiYY))*(a*phiX*t + 1)))/std::pow(J, 7)
    };
}

template<class Scalar>
Scalar fluidSource(Scalar x, Scalar y, Scalar t, Scalar alpha, Scalar Sp, Scalar kappa0, Scalar mu)
{
    const auto [phi, phiX, phiY, phiXX, phiXY, phiYY] = phiDerivatives(x, y);
    const auto [psi, psiX, psiY, psiXX, psiXY, psiYY] = psiDerivatives(x, y);
    return (-2*kappa0*phiXY*psiX*std::pow(t, 2)*(std::pow(a, 2)*phiY*t + b*(b*phiY*t + 1))
        - 2*kappa0*phiXY*psiY*std::pow(t, 2)*(a*(a*phiX*t + 1) + std::pow(b, 2)*phiX*t)
        + kappa0*psiX*std::pow(t, 2)*(std::pow(a, 2)*phiXY*phiY*t + a*phiYY*(a*phiX*t + 1)
        + std::pow(b, 2)*phiX*phiYY*t + b*phiXY*(b*phiY*t + 1))
        - kappa0*psiXX*t*(std::pow(a, 2)*std::pow(phiY, 2)*std::pow(t, 2) + std::pow(b*phiY*t
        + 1, 2)) + 2*kappa0*psiXY*std::pow(t, 2)*(a*phiY*(a*phiX*t + 1) + b*phiX*(b*phiY*t + 1))
        + kappa0*psiY*std::pow(t, 2)*(std::pow(a, 2)*phiXX*phiY*t + a*phiXY*(a*phiX*t + 1)
        + std::pow(b, 2)*phiX*phiXY*t + b*phiXX*(b*phiY*t + 1))
        - kappa0*psiYY*t*(std::pow(b, 2)*std::pow(phiX, 2)*std::pow(t, 2) + std::pow(a*phiX*t
        + 1, 2)) + mu*(Sp*psi + alpha*(a*phiX + b*phiY)))/mu;
}

} // end namespace Dumux::PoroElasticLargeDefMMS

#endif
